  //#region AlertProvider
  type AlertProviderProps = {
    children: React.ReactNode;
  };
  type AlertProvider = React.FC<AlertProviderProps>;

  type AddAlertProps = {
    duration?: number;
    id?: string;
    message: string;
    severity: Severity;
    variant?: Variant;
  };
  export type AddAlert = (alert: AddAlertProps) => void;

  type RemoveAllAlerts = () => void;

  type UseAlert = () => {
    addAlert: AddAlert;
    removeAllAlerts: RemoveAllAlerts;
  };

  export const AlertProvider: AlertProvider;
  export const useAlert: UseAlert;
  //#endregion

